"""Run explicitly with staged public weights. A missing prerequisite exits nonzero."""

from __future__ import annotations

import argparse
import contextlib
import hashlib
import importlib.metadata
import json
import os
import shutil
import subprocess
import sys
import time
from collections.abc import Callable, Sequence
from pathlib import Path
from typing import Any

REPO = Path(__file__).resolve().parents[3]
SCRIPT = REPO / "training/profiles/qualify_open_weight.py"
# Independently generated by Transformers 4.49.0 + torch 2.6.0+cpu, float32/eager.
REFERENCE_LOGITS = [
    [31.629457473754883, 31.486942291259766],
    [31.73869514465332, 31.391284942626953],
]
TOKEN_IDS = "2a16af65bf9f9d493a3d9773208bed3e27668fd2fdb2711bc7088a3eb377ee40"


PAYLOADS = {
    "numpy": "783a80651f5506bbc41b83108b985df21448c9242e1c8ae25105b2d199a32643",
    "tokenizers": "16413eb3914d8fc62e3d977ea90a59b3e66133199094df080bf7222035f762aa",
}


def verified_profile(base: Path) -> dict[str, Any]:
    """Check the publisher's staged assets before allocating a worker or creating fit evidence."""
    profile: dict[str, Any] = json.loads(
        (REPO / "training/profiles/smollm2_135m_lora_v1.json").read_bytes()
    )
    for name, expected in profile["files"].items():
        file = base / name
        if file.is_symlink() or not file.is_file():
            raise SystemExit(
                json.dumps({"state": "held", "reason": "staged_model_file_required", "file": name})
            )
        with file.open("rb") as handle:
            if hashlib.file_digest(handle, "sha256").hexdigest() != expected:
                raise SystemExit(
                    json.dumps(
                        {"state": "held", "reason": "staged_model_hash_mismatch", "file": name}
                    )
                )
    return profile


def reference(base: Path, wheel_dir: Path | None = None) -> None:
    profile = verified_profile(base)
    sys.path.insert(0, str(REPO / "training/src/opentour_training/training"))
    import numpy as np
    import open_weight_worker as worker
    import tokenizers

    packages = {}
    for name, expected in PAYLOADS.items():
        distribution = importlib.metadata.distribution(name)
        paths = sorted(
            str(path)
            for path in distribution.files or []
            if path.parts[0] in {name, name + ".libs"}
            and "__pycache__" not in path.parts
            and path.suffix != ".pyc"
        )
        aggregate = hashlib.sha256()
        for path in paths:
            with Path(str(distribution.locate_file(path))).open("rb") as handle:
                aggregate.update(
                    path.encode() + b"\0" + hashlib.file_digest(handle, "sha256").digest()
                )
        assert aggregate.hexdigest() == expected, "installed payload differs from the locked wheel"
        packages[name] = {"payload_sha256": expected, "verified_package_files": len(paths)}
        if wheel_dir is not None:
            (wheel,) = wheel_dir.glob(f"{name}-{profile['runtime'][name]}-*.whl")
            with wheel.open("rb") as handle:
                sha = hashlib.file_digest(handle, "sha256").hexdigest()
            assert sha == profile["runtime"][name + "_wheel_sha256"]
            packages[name]["wheel_sha256"] = sha
    tok = tokenizers.Tokenizer.from_file(str(base / "tokenizer.json"))
    texts = [{"question": "refund on invoice"}, {"question": "software crashes during upload"}]
    seq = [tok.encode(worker.prompt(row, ["billing", "technical"])).ids for row in texts]
    ids = json.dumps(seq, separators=(",", ":")).encode()
    assert hashlib.sha256(ids).hexdigest() == TOKEN_IDS
    with contextlib.ExitStack() as stack:
        wf = stack.enter_context((base / "model.safetensors").open("rb"))
        frozen = worker.FrozenModel(np, wf, json.loads((base / "config.json").read_bytes()), stack)
        actual = frozen.hidden(seq) @ frozen.weight("model.embed_tokens.weight", [49, 50]).T
    difference = float(np.max(np.abs(actual - np.asarray(REFERENCE_LOGITS))))
    assert difference < 3e-4, "frozen logits differ from the public Transformers implementation"
    print(
        json.dumps(
            {
                "reference_max_absolute_logit_difference": difference,
                "token_ids_sha256": TOKEN_IDS,
                "runtime_packages": packages,
            }
        )
    )


def _numeric_children(pid: int) -> list[Path]:
    children = []
    for child in Path("/proc").glob("[0-9]*"):
        try:
            status = (child / "status").read_text()
            command_line = (child / "cmdline").read_bytes()
        except OSError:
            continue
        if f"PPid:\t{pid}\n" in status and b"open_weight_worker.py" in command_line:
            children.append(child)
    return children


def execute(work: Path, base: Path, python: Path, wheel_dir: Path | None = None) -> None:
    sys.path[:0] = [str(REPO / "services/cell-runtime/src"), str(REPO / "training/profiles")]
    import qualify_open_weight as qualify
    from opentour_cell.pilot import open_weight as model

    verified_profile(base)
    work.mkdir(mode=0o700, parents=True, exist_ok=True)
    if any(work.iterdir()):
        raise SystemExit("use a new empty private qualification directory")
    environment = {
        "PYTHONPATH": str(REPO / "services/cell-runtime/src"),
        "LANG": "C.UTF-8",
        "OMP_NUM_THREADS": "1",
        "OPENBLAS_NUM_THREADS": "1",
        "TOKENIZERS_PARALLELISM": "false",
        "HF_HUB_OFFLINE": "1",
        "TRANSFORMERS_OFFLINE": "1",
    }

    def command(phase: str, dest: Path = work, executable: Path = python) -> list[str]:
        return [
            sys.executable,
            str(SCRIPT),
            phase,
            "--work-dir",
            str(dest),
            "--model-dir",
            str(base),
            "--numeric-python",
            str(executable),
        ]

    def fresh(args: Sequence[str]) -> bytes:
        return subprocess.run(args, env=environment, check=True, capture_output=True).stdout

    def failure(call: Callable[[], Any], reason: str) -> None:
        try:
            call()
        except model.OpenWeightError as exc:
            assert str(exc) == reason, (exc, reason)
        else:
            raise AssertionError("adverse case was accepted: " + reason)

    fresh(command("prepare"))
    ref_args = [str(python), str(Path(__file__).resolve()), "reference", str(base)]
    if wheel_dir is not None:
        ref_args.append(str(wheel_dir))
    golden = json.loads(fresh(ref_args))
    first = json.loads(fresh(command("fit")))
    manifest = (work / "model/manifest.json").read_bytes()
    # Deliberately unavailable interpreter proves a completed, identical retry did no refit.
    retry = json.loads(fresh(command("fit", executable=work / "absent-interpreter")))
    assert first == retry and (work / "model/manifest.json").read_bytes() == manifest
    first_replay = json.loads(fresh(command("replay-first")))
    second_replay = json.loads(fresh(command("replay-repeat")))
    assert first_replay["output_sha256"] == second_replay["output_sha256"]
    report = json.loads(fresh(command("verify")))
    assert report["simple_route"] == "simple" and report["simple_fit_calls"] == 0
    assert list(first["training"]["changed_parameters"]) == [2304, 8]
    assert list(first["training"]["nonzero_parameters"]) == [2304, 8]
    assert first["training"]["initial_loss"] > first["training"]["final_loss"]
    assert first["training"]["verified_base_sha256"] == model.BASE_SHA256
    assert report["protected_count"] == 5 and report["fallback"] == {"status": "review"}
    assert report["real_customer_acceptances"] == report["aws_resources_provisioned"] == 0
    grant = qualify.read(work / "grant.json")
    feature = {"question": "Please explain our invoice."}

    def predict(bundle: Path, directory: Path, actual: dict[str, Any]) -> dict[str, str]:
        decision: dict[str, str] = model.predict_open_weight(
            bundle, feature, model_dir=directory, grant=actual, python=python
        )
        return decision

    # Altered inputs use separate directories from the publisher files and good output.
    incorrect = work / "wrong-base"
    incorrect.mkdir()
    for name in ("model.safetensors", "config.json", "tokenizer.json", "tokenizer_config.json"):
        source, dest = base / name, incorrect / name
        if name == "model.safetensors":
            dest.write_bytes(b"generated incorrect public weight fixture")
        else:
            shutil.copyfile(source, dest)
    failure(lambda: predict(work / "model", incorrect, grant), "staged_model_hash_mismatch")
    (incorrect / "model.safetensors").unlink()
    try:
        os.link(base / "model.safetensors", incorrect / "model.safetensors")
    except OSError:
        shutil.copyfile(base / "model.safetensors", incorrect / "model.safetensors")
    (incorrect / "tokenizer.json").write_text("{}")
    failure(lambda: predict(work / "model", incorrect, grant), "staged_model_hash_mismatch")
    corrupt = work / "corrupt-adapter"
    shutil.copytree(work / "model", corrupt)
    adapter = json.loads((corrupt / "adapter.json").read_bytes())
    adapter["a"] = "AAAA"
    (corrupt / "adapter.json").write_text(json.dumps(adapter))
    failure(lambda: predict(corrupt, base, grant), "open_weight_artifact_mismatch")
    failure(
        lambda: predict(work / "model", base, dict(grant, compute_authorized=False)),
        "model_compute_data_and_destination_approval_required",
    )
    failure(
        lambda: predict(work / "model", base, dict(grant, expires_at=1)),
        "current_open_weight_permission_required",
    )
    failure(
        lambda: predict(work / "model", base, dict(grant, trainer="other")),
        "open_weight_grant_mismatch",
    )
    assert model.predict_open_weight(
        work / "model", {"question": "a " * 510 + "x"}, model_dir=base, grant=grant, python=python
    ) == {"status": "review"}
    rows = qualify.read(work / "training.json")
    rows[0]["features"]["question"] += " Amend."
    failure(
        lambda: model.fit_open_weight(
            work / "model",
            rows,
            model_dir=base,
            grant=grant,
            residual=qualify.read(work / "residual.json"),
            protected_fingerprints=qualify.read(work / "protected-keys.json"),
            python=python,
        ),
        "open_weight_fit_conflict",
    )
    held = work / "withdrawal"
    fresh(command("prepare", held))
    with subprocess.Popen(
        command("fit", held), stdout=subprocess.PIPE, stderr=subprocess.PIPE, env=environment
    ) as fitting:
        deadline = time.monotonic() + 10
        while time.monotonic() < deadline and fitting.poll() is None:
            if _numeric_children(fitting.pid):
                break
            time.sleep(0.01)
        else:
            fitting.kill()
            raise AssertionError("no real numeric subprocess was observed for cancellation")
        model.withdraw_open_weight(held / "model", grant=grant)
        _out, err = fitting.communicate(timeout=5)
    assert fitting.returncode != 0 and b"open_weight_authority_withdrawn" in err
    assert not (held / "model").exists() and not list(held.glob(".model.pending-*"))
    denied = subprocess.run(command("fit", held), env=environment, capture_output=True)
    assert denied.returncode != 0 and b"open_weight_authority_withdrawn" in denied.stderr

    def deny_active(call: Callable[[Callable[[], None]], Any]) -> None:
        observed: list[Path] = []
        began = 0.0

        def check() -> None:
            nonlocal began
            if not observed:
                observed.extend(_numeric_children(os.getpid()))
                if observed:
                    began = time.monotonic()
            if observed and time.monotonic() - began > 0.25:
                raise model.OpenWeightError("source_scope_withdrawn")

        failure(lambda: call(check), "source_scope_withdrawn")
        assert observed and all(not child.exists() for child in observed)

    def fit_with_guard(target: Path, check: Callable[[], None]) -> dict[str, Any]:
        value: dict[str, Any] = model.fit_open_weight(
            target,
            qualify.read(work / "training.json"),
            model_dir=base,
            grant=grant,
            residual=qualify.read(work / "residual.json"),
            protected_fingerprints=qualify.read(work / "protected-keys.json"),
            python=python,
            check_permission=check,
        )
        return value

    partial = work / "source-canceled-fit"
    deny_active(lambda check: fit_with_guard(partial, check))
    assert not partial.exists() and not list(work.glob(".source-canceled-fit.pending-*"))
    deny_active(
        lambda check: model.predict_open_weight_batch(
            work / "model",
            [feature],
            model_dir=base,
            grant=grant,
            python=python,
            check_permission=check,
        )
    )
    postrename = work / "source-canceled-on-publication"

    def last_check() -> None:
        if postrename.exists():
            raise model.OpenWeightError("source_scope_withdrawn")

    failure(lambda: fit_with_guard(postrename, last_check), "source_scope_withdrawn")
    assert not postrename.exists() and not list(
        work.glob(".source-canceled-on-publication.pending-*")
    )
    slow_rows = [
        {
            "case_id": f"slow-{i}",
            "family_id": f"slow-family-{i}",
            "features": {"question": raw + " Additional context." * 30 + f" Record {i}."},
            "label": label,
        }
        for i in range(32)
        for raw, label in [qualify.TRAIN[i % len(qualify.TRAIN)]]
    ]
    slow_residual = qualify.development(slow_rows, simple=False)
    slow_grant = dict(grant, max_seconds=1, residual_revision=slow_residual["revision"])
    started = time.monotonic()
    try:
        model.fit_open_weight(
            work / "expired-work",
            slow_rows,
            model_dir=base,
            grant=slow_grant,
            residual=slow_residual,
            protected_fingerprints=qualify.read(work / "protected-keys.json"),
            python=python,
        )
    except model.OpenWeightError as exc:
        assert str(exc) in {"open_weight_deadline_exceeded", "worker_interrupted_or_resource_limit"}
        deadline_reason = str(exc)
    else:
        raise AssertionError("the resource-bound stress workload finished within one second")
    assert not (work / "expired-work").exists()
    assert time.monotonic() - started < 3
    report.update(
        deadline_hold=deadline_reason,
        exact_public_reference=golden,
        first_replay_ms=first_replay["elapsed_ms"],
        repeated_replay_ms=second_replay["elapsed_ms"],
        identical_retry_without_compute=True,
        adverse_checks=[
            "wrong_base",
            "wrong_tokenizer",
            "corrupt_adapter",
            "missing_compute",
            "expired_grant",
            "other_owner",
            "context_overflow_reviews",
            "conflicting_retry",
            "cancel_live_fit",
            "durable_withdrawal",
            "real_worker_time_budget",
            "source_cancel_live_fit",
            "source_cancel_live_inference",
            "source_cancel_at_atomic_publish",
        ],
    )
    qualify.record(work / "qualification-result.json", report)
    print(json.dumps(report, sort_keys=True))


def test_missing_source_holds_without_allocating_a_worker(tmp_path: Path) -> None:
    _expect_source_hold(tmp_path, "staged_model_file_required")


def test_substituted_source_cannot_produce_a_qualification_receipt(tmp_path: Path) -> None:
    base = tmp_path / "model-base"
    base.mkdir()
    profile = json.loads((REPO / "training/profiles/smollm2_135m_lora_v1.json").read_bytes())
    for name in profile["files"]:
        (base / name).write_bytes(b"generated substitute for a publisher asset")
    _expect_source_hold(tmp_path, "staged_model_hash_mismatch")


def _expect_source_hold(directory: Path, reason: str) -> None:
    output = directory / "qualification"
    run = subprocess.run(
        [
            sys.executable,
            str(Path(__file__).resolve()),
            "--model-dir",
            str(directory / "model-base"),
            "--numeric-python",
            str(directory / "unavailable-worker"),
            "--work-dir",
            str(output),
        ],
        capture_output=True,
        check=False,
    )
    assert run.returncode != 0
    issue = json.loads(run.stderr)
    assert issue["state"] == "held" and issue["reason"] == reason
    assert not output.exists()


if __name__ == "__main__":
    if sys.argv[1:2] == ["reference"]:
        reference(Path(sys.argv[2]), Path(sys.argv[3]) if len(sys.argv) > 3 else None)
    else:
        parser = argparse.ArgumentParser(description=__doc__)
        parser.add_argument("--model-dir", type=Path, required=True)
        parser.add_argument("--numeric-python", type=Path, required=True)
        parser.add_argument("--work-dir", type=Path, required=True)
        parser.add_argument(
            "--wheel-dir", type=Path, help="also verify the two original staged wheels"
        )
        args = parser.parse_args()
        execute(
            args.work_dir.absolute(),
            args.model_dir.absolute(),
            args.numeric_python.absolute(),
            args.wheel_dir,
        )
